# PRESERVED_ITEM_APPEARANCE_V4: original approved appearance on every export.
from pathlib import Path
import base64

SETTINGS = {50033: ('Losowe bronie', 'Zawiera losową broń na 30 poziom.'), 50035: ('Skrzynia z KU', 'Zawiera jedną losową księgę umiejętności.'), 50122: ('Dodania i zmianki', 'Zmianki i dodania bonusu.'), 50124: ('Spróchniała Skrzynia', 'Zielone zmianki i dodania bonusu do broni i zbroi do 40 poziomu.'), 71102: ('Klepsydra Biologa', 'Zeruje aktywny czas oczekiwania u Biologa. Zuzywa jedna sztuke. Nie zwieksza szansy powodzenia badan.')}
ICON_B64 = {'icon/item/klepsydra_biologa_71102.tga': '', 'icon/item/custom_chest_50122.tga': '', 'icon/item/custom_chest_50035.tga': '', 'icon/item/skrzynia_zielone_bonusy_50124.tga': '', 'icon/item/custom_chest_50033.tga': ''}

# CUSTOM_RECIPE_CHEST_APPEARANCE_V1: preserve all previous icons and export this new item every time.
SETTINGS[59010]=('Skrzynia Receptur','Zawiera jedna losowa recepture wywaru lub mikstury z dropu metinow.')
ICON_B64['icon/item/custom_recipe_chest_59010.tga']=ICON_B64['icon/item/custom_chest_50035.tga']

def icons():
    return {name: base64.b64decode(blob, validate=True) for name, blob in ICON_B64.items()}

def mob_flags(query):
    categories = ('ANIMAL','UNDEAD','DEVIL','HUMAN','ORC','MILGYO','INSECT','FIRE','ICE','DESERT','TREE')
    rows = query('SELECT vnum,`type` AS `type`,`rank` AS `rank`,setRaceFlag FROM world.mob_proto ORDER BY vnum')
    output = ['# CURRENT_MOB_RACE_FLAGS_V2: vnum type rank flags; includes explicit zero']
    seen = set()
    for row in rows:
        vnum = int(row['vnum']); kind = int(row['type']); rank = int(row['rank'])
        if vnum <= 0 or vnum in seen or not 0 <= kind <= 255 or not 0 <= rank <= 255:
            raise RuntimeError('Niepoprawny mob_proto dla podgladu bonusow.')
        seen.add(vnum)
        value = row['setRaceFlag']
        if isinstance(value, bytes): value = value.decode('ascii')
        tokens = set(str(value or '').split(','))
        mask = sum(1 << i for i, name in enumerate(categories) if name in tokens)
        output.append('%d\t%d\t%d\t%d' % (vnum,kind,rank,mask))
    if not seen: raise RuntimeError('Puste mob_proto: eksport bonusow przerwany.')
    return ('\n'.join(output)+'\n').encode('ascii')

def extend(query, base, files, summary):
    from . import clientfiles, dbdata
    from .appearance_pack import ICON_PATHS, patch_item_list
    # Include the complete new proto row even without panel edit history.
    from .dbsource import _item_rows
    recipe_rows=_item_rows(query,{59010})
    if 59010 not in recipe_rows:raise RuntimeError('Brak Skrzyni Receptur59010 w bazie.')
    files['gamedata/item_proto'],_=clientfiles.patch_item_proto(files['gamedata/item_proto'],{59010:None},recipe_rows,summary.setdefault('notes',[]))
    ICON_PATHS[59010]='icon/item/custom_recipe_chest_59010.tga'
    key = 'gamedata/item_list.txt'
    source = files.get(key)
    if source is None:
        if key in base.names():
            source = base.file(key)
        else:
            source = Path(__file__).with_name('custom_material_item_list.base.txt').read_bytes()
    if not any(line.split(b'\t',1)[0].strip()==b'59010' for line in source.splitlines()):
        template=next(line for line in source.splitlines() if line.split(b'\t',1)[0].strip()==b'50035')
        parts=template.split(b'\t');parts[0]=b'59010';parts[2]=b'icon/item/custom_recipe_chest_59010.tga'
        ending=b'\r\n' if b'\r\n' in source else b'\n'
        source=source+(b'' if source.endswith((b'\n',b'\r')) else ending)+b'\t'.join(parts)+ending
    files[key] = patch_item_list(source, ICON_PATHS)
    payload = icons()
    files.update(payload)
    dbdata.OPTIONAL_FILES.update({name: 2 for name in [key] + list(payload)})
    wanted = ','.join(str(v) for v in sorted(SETTINGS))
    rows = query('SELECT vnum, CAST(locale_name AS BINARY) AS locale_name_bytes FROM world.item_proto WHERE vnum IN (' + wanted + ')')
    names = {int(row['vnum']): row.get('locale_name_bytes', row.get('locale_name')) for row in rows}
    if set(names) != set(SETTINGS):
        raise RuntimeError('Brakuje jednego z 5 przedmiotow wygladu w bazie.')
    if any(value is None for value in names.values()):
        raise RuntimeError('Brak nazwy przedmiotu w eksporcie.')
    files['gamedata/item_proto'], _ = clientfiles.patch_item_proto(files['gamedata/item_proto'], {v: {'locale_name'} for v in SETTINGS}, {v: {'locale_name': value} for v, value in names.items()}, summary.setdefault('notes', []))
    desc = {v: {1: clientfiles._text(names[v]), 2: SETTINGS[v][1], 3: ''} for v in SETTINGS}
    files['locale/pl/itemdesc.txt'], _ = clientfiles.patch_tab_text(files['locale/pl/itemdesc.txt'], desc, 4)
    summary['preserved_appearance_v4'] = sorted(SETTINGS)
    flag_name = 'gamedata/mob_race_flags.txt'
    files[flag_name] = mob_flags(query)
    dbdata.OPTIONAL_FILES[flag_name] = 2
    return files, summary
